DELIMITER ;;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;;
/*!50003 SET character_set_client  = utf8mb4 */ ;;
/*!50003 SET character_set_results = utf8mb4 */ ;;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;;
/*!50003 SET @saved_time_zone      = @@time_zone */ ;;
/*!50003 SET time_zone             = 'SYSTEM' */ ;;
/*!50106 CREATE*/ /*!50117 DEFINER=`miguelveigamacedo`@`localhost`*/ /*!50106 EVENT `etl_update_downtime_event` ON SCHEDULE EVERY 1 MINUTE STARTS '2025-12-05 10:32:14' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN

    /* 1) Insert new events (no duplicates), with deltas + product + speed */
    INSERT INTO mes_core.downtime_event (
        raw_event_id,
        machine_id,
        product_id,
        workorder,
        raw_reason_code,
        start_ts,
        end_ts,
        duration_sec,
        shift_id,
        units_total,
        waste_total,
        target_speed_ups,
        reason_code_id,
        comment,
        source_quality
    )
    SELECT
        mse.Id                              AS raw_event_id,
        m.id                                AS machine_id,

        /* product from order_run if present, else STANDARD_PRODUCT */
        COALESCE(orun.product_id, p_std.id) AS product_id,

        mse.WorkOrder                       AS workorder,
        mse.ReasonCode                      AS raw_reason_code,
        mse.Ts                              AS start_ts,
        NULL                                AS end_ts,
        NULL                                AS duration_sec,
        mse.ShiftId                         AS shift_id,

        /* good units during this event (delta from previous snapshot) */
        GREATEST(
            mse.UnitsTotal
            - COALESCE(
                LAG(mse.UnitsTotal) OVER (
                    PARTITION BY mse.MachineId, mse.WorkOrder
                    ORDER BY mse.Ts
                ),
                0
              ),
            0
        )                                   AS units_total,

        /* scrap units during this event (delta from previous snapshot) */
        GREATEST(
            mse.WasteTotal
            - COALESCE(
                LAG(mse.WasteTotal) OVER (
                    PARTITION BY mse.MachineId, mse.WorkOrder
                    ORDER BY mse.Ts
                ),
                0
              ),
            0
        )                                   AS waste_total,

        /* target speed already in units/second */
        COALESCE(p.nominal_speed, p_std.nominal_speed) AS target_speed_ups,

        NULL                                AS reason_code_id,  -- mapped in step 4
        NULL                                AS comment,
        'AUTO'                              AS source_quality
    FROM mes.MachineStatusEvent mse
    JOIN mes_core.machine m
      ON m.code = mse.MachineId
    LEFT JOIN mes_core.order_run orun
      ON orun.workorder = mse.WorkOrder
     AND orun.machine_id = m.id
    LEFT JOIN mes_core.product p
      ON p.id = orun.product_id
    JOIN mes_core.product p_std
      ON p_std.code = 'STANDARD_PRODUCT'
    LEFT JOIN mes_core.downtime_event de
      ON de.raw_event_id = mse.Id
    WHERE de.raw_event_id IS NULL
      AND mse.Ts >= NOW() - INTERVAL 24 HOUR;


    /* 2) Set end_ts from next event timestamp per machine */
    WITH ordered AS (
        SELECT
            mse.Id,
            mse.MachineId,
            mse.Ts,
            LEAD(mse.Ts) OVER (
                PARTITION BY mse.MachineId
                ORDER BY mse.Ts
            ) AS next_ts
        FROM mes.MachineStatusEvent mse
        WHERE mse.Ts >= NOW() - INTERVAL 24 HOUR
    )
    UPDATE mes_core.downtime_event de
    JOIN ordered o
      ON o.Id = de.raw_event_id
    SET de.end_ts = o.next_ts
    WHERE de.end_ts IS NULL
      AND o.next_ts IS NOT NULL;


    /* 3) Recalculate duration_sec for recent events */
    UPDATE mes_core.downtime_event
    SET duration_sec = TIMESTAMPDIFF(
            SECOND,
            start_ts,
            COALESCE(end_ts, NOW())
        )
    WHERE start_ts >= NOW() - INTERVAL 24 HOUR;


    /* 4) Map raw_reason_code -> reason_code_id for AUTO events */
    UPDATE mes_core.downtime_event de
    LEFT JOIN mes_core.reason_code rc
           ON rc.code = TRIM(de.raw_reason_code)
           OR rc.code = CONCAT('[AUTO] ', TRIM(de.raw_reason_code))
    SET de.reason_code_id = rc.id
    WHERE de.start_ts >= NOW() - INTERVAL 24 HOUR
      AND de.source_quality = 'AUTO';

END */ ;;
