/*!50106 SET @save_time_zone= @@TIME_ZONE */ ;
/*!50106 DROP EVENT IF EXISTS `etl_sync_order_run_shift` */;
DELIMITER ;;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;;
/*!50003 SET character_set_client  = utf8mb4 */ ;;
/*!50003 SET character_set_results = utf8mb4 */ ;;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;;
/*!50003 SET @saved_time_zone      = @@time_zone */ ;;
/*!50003 SET time_zone             = 'SYSTEM' */ ;;
/*!50106 CREATE*/ /*!50117 DEFINER=`miguelveigamacedo`@`localhost`*/ /*!50106 EVENT `etl_sync_order_run_shift` ON SCHEDULE EVERY 5 MINUTE STARTS '2025-12-03 18:11:36' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
    -- Build temporary aggregates from recent data
    DROP TEMPORARY TABLE IF EXISTS tmp_order_run_shift;

    CREATE TEMPORARY TABLE tmp_order_run_shift AS
    WITH ordered AS (
        SELECT
            mse.Id,
            mse.MachineId,
            mse.WorkOrder,
            mse.StatusCode,
            mse.UnitsTotal,
            mse.WasteTotal,
            mse.ShiftId,
            mse.Ts,
            LEAD(mse.Ts) OVER (
                PARTITION BY mse.MachineId
                ORDER BY mse.Ts
            ) AS next_ts
        FROM mes.MachineStatusEvent mse
        WHERE mse.Ts >= NOW() - INTERVAL 2 DAY
          AND mse.WorkOrder IS NOT NULL
          AND mse.WorkOrder <> ''
    )
    SELECT
        m.id        AS machine_id,
        o.WorkOrder AS workorder,
        o.ShiftId   AS shift_id,
        MAX(o.UnitsTotal) - MIN(o.UnitsTotal) AS qty_good,
        MAX(o.WasteTotal) - MIN(o.WasteTotal) AS qty_scrap,
        SUM(
            CASE 
                WHEN o.StatusCode = 'RUNNING' THEN
                    TIMESTAMPDIFF(
                        SECOND,
                        o.Ts,
                        COALESCE(o.next_ts, NOW())
                    )
                ELSE 0
            END
        ) AS runtime_sec
    FROM ordered o
    JOIN mes_core.machine m
      ON m.code = o.MachineId
    GROUP BY
        m.id,
        o.WorkOrder,
        o.ShiftId;

    -- Upsert into mes_core.order_run_shift
    INSERT INTO mes_core.order_run_shift (
        workorder,
        machine_id,
        shift_id,
        qty_good,
        qty_scrap,
        runtime_sec
    )
    SELECT
        t.workorder,
        t.machine_id,
        t.shift_id,
        t.qty_good,
        t.qty_scrap,
        t.runtime_sec
    FROM tmp_order_run_shift t
    ON DUPLICATE KEY UPDATE
        qty_good    = VALUES(qty_good),
        qty_scrap   = VALUES(qty_scrap),
        runtime_sec = VALUES(runtime_sec);
END */ ;;
/*!50003 SET time_zone             = @saved_time_zone */ ;;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;;
/*!50003 SET character_set_client  = @saved_cs_client */ ;;
/*!50003 SET character_set_results = @saved_cs_results */ ;;
/*!50003 SET collation_connection  = @saved_col_connection */ ;;
DELIMITER ;
/*!50106 SET TIME_ZONE= @save_time_zone */ ;

--
-- Dumping routines for database 'mes'
--
/*!50003 DROP PROCEDURE IF EXISTS `populate_shifts_4months` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`miguelveigamacedo`@`localhost` PROCEDURE `populate_shifts_4months`()
BEGIN
    DECLARE d DATE;

    SET d = DATE_SUB(CURDATE(), INTERVAL 60 DAY);
    WHILE d <= DATE_ADD(CURDATE(), INTERVAL 60 DAY) DO
        
        -- Morning shift 06:00–14:00
        INSERT IGNORE INTO mes.shift (
            shift_code, shift_type, shift_date, start_ts, end_ts, is_active
        ) VALUES (
            CONCAT('MOR_', DATE_FORMAT(d, '%d-%m-%y')),
            'MOR',
            d,
            CONCAT(d, ' 06:00:00'),
            CONCAT(d, ' 14:00:00'),
            1
        );

        -- Afternoon shift 14:00–22:00
        INSERT IGNORE INTO mes.shift (
            shift_code, shift_type, shift_date, start_ts, end_ts, is_active
        ) VALUES (
            CONCAT('AFT_', DATE_FORMAT(d, '%d-%m-%y')),
            'AFT',
            d,
            CONCAT(d, ' 14:00:00'),
            CONCAT(d, ' 22:00:00'),
            1
        );

        -- Night shift 22:00–06:00 next day
        INSERT IGNORE INTO mes.shift (
            shift_code, shift_type, shift_date, start_ts, end_ts, is_active
        ) VALUES (
            CONCAT('NIG_', DATE_FORMAT(d, '%d-%m-%y')),
            'NIG',
            d,
            CONCAT(d, ' 22:00:00'),
            CONCAT(DATE_ADD(d, INTERVAL 1 DAY), ' 06:00:00'),
            1
        );

        SET d = DATE_ADD(d, INTERVAL 1 DAY);
    END WHILE;
END ;;
DELIMITER ;
